   array['XS','S','M','L','XL','XXL'], '/seed/sweat-capuche.webp', 'Maison Aune', 'https://example.com/maison-aune/sweat?aff=checkmyfit', true, true),
  ('DEMO-002', 'nord-atelier-chemise-popeline-cintree', 'Chemise Popeline Cintrée', 'Nord Atelier', 'Chemise manches longues', 'Homme', 79, 'Noir',
   'Chemise en popeline de coton, coupe cintrée et col italien. Se porte fermée pour un rendu strict ou ouverte sur un t-shirt.',
   'Lavage machine à 30°C. Repassage à température moyenne. Nettoyage à sec accepté.', 'Fabriqué en Turquie',
   'Coupe ajustée : prenez une taille au-dessus si vous préférez plus d''aisance aux épaules.',
   array['S','M','L','XL'], '/seed/chemise-popeline-noire.webp', 'Nord Atelier', 'https://example.com/nord-atelier/chemise?aff=checkmyfit', false, true),
  ('DEMO-003', 'solstice-robe-drapee-emeraude', 'Robe Drapée Émeraude', 'Solstice', 'Robe', 'Femme', 139, 'Vert émeraude',
   'Robe moulante à fines bretelles, drapé fronce sur l''avant qui affine la silhouette. Tissu stretch qui accompagne le mouvement.',
   'Lavage à la main, à froid. Ne pas essorer. Séchage à plat, à l''ombre.', 'Fabriqué en Espagne',
   'Taille normalement grâce au tissu extensible ; prenez une taille en dessous pour un maintien plus ferme.',
   array['XS','S','M','L'], '/seed/robe-drapee-emeraude.webp', 'Solstice', 'https://example.com/solstice/robe?aff=checkmyfit', true, true),
  ('DEMO-004', 'ferro-co-blouse-satinee-portefeuille', 'Blouse Satinée Portefeuille', 'Ferro & Co', 'Chemise manches longues', 'Femme', 99, 'Orange cuivré',
   'Blouse portefeuille en satin, manches longues à poignets froncés. Une pièce qui capte la lumière, à porter en soirée ou au bureau.',
   'Nettoyage à sec uniquement. Repassage à basse température, à l''envers du tissu.', 'Fabriqué en Italie',
   'Coupe fluide et ample : prenez votre taille habituelle.',
   array['XS','S','M','L','XL'], '/seed/blouse-satinee-orange.webp', 'Ferro & Co', 'https://example.com/ferro/blouse?aff=checkmyfit', false, true),
  ('DEMO-005', 'brune-chemise-oxford-ajustee', 'Chemise Oxford Ajustée', 'Brune', 'Chemise manches longues', 'Femme', 69, 'Bleu ciel',
   'Chemise Oxford en coton, coupe ajustée et col boutonné classique. Un basique solide qui se repasse facilement.',
   'Lavage machine à 40°C. Repassage à température moyenne. Sèche-linge autorisé à basse température.', 'Fabriqué au Portugal',
   'Coupe ajustée : prenez votre taille habituelle, une taille au-dessus pour plus d''aisance.',
   array['XS','S','M','L','XL'], '/seed/chemise-oxford-bleue.webp', 'Brune', 'https://example.com/brune/oxford?aff=checkmyfit', true, false),
  ('DEMO-006', 'argile-studio-t-shirt-col-rond-essentiel', 'T-shirt Col Rond Essentiel', 'Argile Studio', 'T-shirt / Débardeur', 'Femme', 39, 'Blanc',
   'T-shirt en coton peigné, col rond et coupe droite. La base de tout vestiaire, pensée pour durer au lavage.',
   'Lavage machine à 30°C avec des couleurs similaires. Séchage à plat conseillé pour garder sa forme.', 'Fabriqué au Portugal',
   'Coupe droite : taille normalement.',
   array['XS','S','M','L','XL','XXL'], '/seed/tshirt-col-rond-blanc.webp', 'Argile Studio', 'https://example.com/argile/tshirt?aff=checkmyfit', false, false),
  ('DEMO-007', 'argile-studio-escarpins-vernis-talon-aiguille', 'Escarpins Vernis Talon Aiguille', 'Argile Studio', 'Chaussures', 'Femme', 145, 'Rouge laqué',
   'Escarpins en cuir vernis, talon aiguille et bout pointu. Une pièce affirmée qui structure n''importe quelle silhouette.',
   'Essuyez le vernis avec un chiffon doux et sec. Évitez les frottements avec des surfaces abrasives.', 'Fabriqué au Portugal',
   'Chausse légèrement petit : prenez une demi-pointure au-dessus si vous êtes entre deux tailles.',
   array['36','37','38','39','40','41'], '/seed/escarpins-vernis-rouges.webp', 'Argile Studio', 'https://example.com/argile/escarpins?aff=checkmyfit', true, false)
